              if (prev != NULL) {
                  prev->link = ws->step->blocks;
                  ws->step->blocks = ws->part_list;
              }
              ws->step->n_blocks += ws->n_part_blocks;

              ASSERT(countBlocks(ws->step->blocks) == ws->step->n_blocks);
              ASSERT(countOccupied(ws->step->blocks) == ws->step->n_words);
